<?php
require_once __DIR__.'/../../config/config.php';require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../includes/functions.php';require_perm('items.labels');$db=getDB();
$ids=array_values(array_unique(array_filter(array_map('intval',$_GET['id']??[]))));$copies=max(1,min(20,req_int('copies',1)));$items=[];
if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$types=str_repeat('i',count($ids));$st=$db->prepare("SELECT code,name FROM items WHERE is_active=1 AND id IN ($marks) ORDER BY code");$st->bind_param($types,...$ids);$st->execute();$items=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();}
function code39(string $value):string{$patterns=['0'=>'nnnwwnwnn','1'=>'wnnwnnnnw','2'=>'nnwwnnnnw','3'=>'wnwwnnnnn','4'=>'nnnwwnnnw','5'=>'wnnwwnnnn','6'=>'nnwwwnnnn','7'=>'nnnwnnwnw','8'=>'wnnwnnwnn','9'=>'nnwwnnwnn','A'=>'wnnnnwnnw','B'=>'nnwnnwnnw','C'=>'wnwnnwnnn','D'=>'nnnnwwnnw','E'=>'wnnnwwnnn','F'=>'nnwnwwnnn','G'=>'nnnnnwwnw','H'=>'wnnnnwwnn','I'=>'nnwnnwwnn','J'=>'nnnnwwwnn','K'=>'wnnnnnnww','L'=>'nnwnnnnww','M'=>'wnwnnnnwn','N'=>'nnnnwnnww','O'=>'wnnnwnnwn','P'=>'nnwnwnnwn','Q'=>'nnnnnnwww','R'=>'wnnnnnwwn','S'=>'nnwnnnwwn','T'=>'nnnnwnwwn','U'=>'wwnnnnnnw','V'=>'nwwnnnnnw','W'=>'wwwnnnnnn','X'=>'nwnnwnnnw','Y'=>'wwnnwnnnn','Z'=>'nwwnwnnnn','-'=>'nwnnnnwnw','.'=>'wwnnnnwnn',' '=>'nwwnnnwnn','*'=>'nwnnwnwnn'];$v='*'.strtoupper($value).'*';$x=0;$bars='';foreach(str_split($v) as $char){if(!isset($patterns[$char]))continue;foreach(str_split($patterns[$char]) as $i=>$w){$width=$w==='w'?3:1;if($i%2===0)$bars.='<rect x="'.$x.'" y="0" width="'.$width.'" height="38"/>';$x+=$width;}$x+=1;}return '<svg viewBox="-10 0 '.($x+20).' 38" preserveAspectRatio="xMidYMid meet" aria-label="Barcode '.e($value).'">'.$bars.'</svg>';}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Label Barcode — <?=APP_NAME?></title><style>@page{size:A4;margin:8mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;margin:0}.tools{margin:0 0 10px}.labels{display:grid;grid-template-columns:repeat(3,1fr);gap:4mm}.label{height:35mm;border:1px dashed #999;padding:4mm;text-align:center;break-inside:avoid}.name{font-size:12px;font-weight:bold;height:28px;overflow:hidden}.code{font:11px monospace;margin-top:2px}.label svg{width:100%;height:17mm}@media print{.tools{display:none}.label{border:0}}</style></head><body><div class="tools"><button onclick="print()">Cetak</button> <a href="index.php">Kembali</a></div><div class="labels"><?php foreach($items as $item)for($i=0;$i<$copies;$i++):?><div class="label"><div class="name"><?=e($item['name'])?></div><?=code39($item['code'])?><div class="code"><?=e($item['code'])?></div></div><?php endfor;?></div><?php if(!$items):?><p>Pilih barang dari halaman daftar barang.</p><?php endif;?></body></html>
